/**
 * End-to-end tests for the GitHub Action. They run the real bundled
 * action/dist/index.cjs (exactly what GitHub executes) against:
 *   - a temporary git repo with a base commit and a "PR head" commit
 *   - a local HTTP server pretending to be the GitHub API and an OpenAI-compatible API
 */
import { execFileSync, spawn } from "node:child_process";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";

const here = path.dirname(fileURLToPath(import.meta.url));
const bundle = path.join(here, "..", "dist", "index.cjs");

let repo: string;
let baseSha: string;
let headSha: string;
let server: http.Server;
let apiUrl: string;

interface Recorded { method: string; url: string; body: unknown }
let requests: Recorded[] = [];
let existingComments: { id: number; body: string; user?: { type: string } }[] = [];
let commentStatus = 201;

const sh = (cwd: string, ...args: string[]) =>
  execFileSync("git", ["-c", "user.name=T", "-c", "user.email=t@e.com", ...args], { cwd, encoding: "utf8" }).trim();
const write = (rel: string, content: string) => {
  fs.mkdirSync(path.dirname(path.join(repo, rel)), { recursive: true });
  fs.writeFileSync(path.join(repo, rel), content);
};

beforeAll(async () => {
  if (!fs.existsSync(bundle)) throw new Error("Build the action first: npm run build -w @archguard/action");

  repo = fs.mkdtempSync(path.join(os.tmpdir(), "archguard-action-"));
  sh(repo, "init", "-q", "-b", "main");
  write("web/tsconfig.json", JSON.stringify({ compilerOptions: { baseUrl: ".", paths: { "@/*": ["./*"] } } }));
  write("web/app/page.tsx", `import { Card } from "@/components/Card";\nexport default Card;`);
  write("web/components/Card.tsx", `import { fmt } from "@/lib/fmt";\nexport const Card = () => fmt("x");`);
  write("web/lib/fmt.ts", `export const fmt = (s: string) => s;`);
  sh(repo, "add", "-A");
  sh(repo, "commit", "-q", "-m", "base");
  baseSha = sh(repo, "rev-parse", "HEAD");

  // The PR: lib imports a component (layer violation) and creates a cycle.
  write("web/lib/fmt.ts", `import { Card } from "@/components/Card";\nexport const fmt = (s: string) => s + String(Card);`);
  sh(repo, "add", "-A");
  sh(repo, "commit", "-q", "-m", "pr");
  headSha = sh(repo, "rev-parse", "HEAD");

  server = http.createServer((req, res) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      const body = raw ? JSON.parse(raw) : undefined;
      requests.push({ method: req.method!, url: req.url!, body });
      res.setHeader("Content-Type", "application/json");
      if (req.url!.startsWith("/repos/bytebyjay/demo/issues/7/comments") && req.method === "GET") {
        return res.end(JSON.stringify(existingComments));
      }
      if (req.url === "/repos/bytebyjay/demo/issues/7/comments" && req.method === "POST") {
        res.statusCode = commentStatus;
        return res.end(JSON.stringify(commentStatus === 201 ? { id: 99 } : { message: "Resource not accessible by integration" }));
      }
      if (req.url!.startsWith("/repos/bytebyjay/demo/issues/comments/") && req.method === "PATCH") {
        return res.end(JSON.stringify({ id: 55 }));
      }
      if (req.url === "/llm/chat/completions") {
        const sent = JSON.parse(body.messages[1].content).violations as { key: string }[];
        const items = sent.map((v) => ({ key: v.key, explanation: `Explained ${v.key}.`, suggestion: "Move the shared code to lib/." }));
        return res.end(JSON.stringify({ choices: [{ message: { content: JSON.stringify({ items }) } }] }));
      }
      res.statusCode = 404;
      res.end("{}");
    });
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  apiUrl = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
});

afterAll(() => {
  server?.close();
  fs.rmSync(repo, { recursive: true, force: true });
});

beforeEach(() => {
  requests = [];
  existingComments = [];
  commentStatus = 201;
});

function runAction(inputs: Record<string, string>, event: object | null, eventName = "pull_request") {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "archguard-runner-"));
  const eventPath = path.join(tmp, "event.json");
  if (event) fs.writeFileSync(eventPath, JSON.stringify(event));
  const files = { output: path.join(tmp, "output"), summary: path.join(tmp, "summary.md") };
  fs.writeFileSync(files.output, "");
  fs.writeFileSync(files.summary, "");

  const env: NodeJS.ProcessEnv = {
    PATH: process.env.PATH,
    GITHUB_WORKSPACE: repo,
    GITHUB_EVENT_NAME: eventName,
    GITHUB_EVENT_PATH: event ? eventPath : "",
    GITHUB_REPOSITORY: "bytebyjay/demo",
    GITHUB_SERVER_URL: "https://github.com",
    GITHUB_API_URL: apiUrl,
    GITHUB_OUTPUT: files.output,
    GITHUB_STEP_SUMMARY: files.summary,
    RUNNER_TEMP: tmp,
    "INPUT_GITHUB-TOKEN": "ghs_test",
    INPUT_PATH: "web",
  };
  for (const [k, v] of Object.entries(inputs)) env[`INPUT_${k.toUpperCase()}`] = v;

  return new Promise<{ code: number; stdout: string; output: string; summary: string }>((resolve) => {
    const child = spawn(process.execPath, [bundle], { env, cwd: repo });
    let stdout = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stdout += d));
    child.on("close", (code) => {
      resolve({ code: code ?? -1, stdout, output: fs.readFileSync(files.output, "utf8"), summary: fs.readFileSync(files.summary, "utf8") });
      fs.rmSync(tmp, { recursive: true, force: true });
    });
  });
}

const prEvent = () => ({ pull_request: { number: 7, base: { sha: baseSha }, head: { sha: headSha } } });

describe("GitHub Action (bundled)", () => {
  it("comments on a PR with only the issues it introduces, annotates, and fails", async () => {
    const r = await runAction({}, prEvent());
    expect(r.code).toBe(1);

    const post = requests.find((q) => q.method === "POST" && q.url.endsWith("/comments"));
    const body = (post?.body as { body: string }).body;
    expect(body).toContain("<!-- archguard:pr-comment -->");
    expect(body).toContain("**Health: 100 →");
    expect(body).toContain("Circular dependency");
    expect(body).toContain("`lib -> components`");
    expect(body).toContain(`https://github.com/bytebyjay/demo/blob/${headSha}/web/lib/fmt.ts#L1`);

    expect(r.stdout).toMatch(/::error file=web\/lib\/fmt\.ts,line=1,title=ArchGuard%3A layer-violation::/);
    expect(r.output).toMatch(/introduced=2/);
    expect(r.output).toMatch(/health-delta=-\d+/);
    expect(r.summary).toContain("ArchGuard architecture check");
  });

  it("updates its existing comment instead of posting a second one", async () => {
    existingComments = [{ id: 1, body: "unrelated" }, { id: 7, body: "<!-- archguard:pr-comment -->\nforged", user: { type: "User" } },
      { id: 55, body: "<!-- archguard:pr-comment -->\nold", user: { type: "Bot" } },
    ];
    await runAction({}, prEvent());
    expect(requests.some((q) => q.method === "POST")).toBe(false);
    expect(requests.find((q) => q.method === "PATCH")?.url).toBe("/repos/bytebyjay/demo/issues/comments/55");
  });

  it("adds AI explanations when an API key is provided", async () => {
    const r = await runAction({ "OPENAI-API-KEY": "sk-test", "OPENAI-BASE-URL": `${apiUrl}/llm` }, prEvent());
    const body = (requests.find((q) => q.method === "POST" && q.url.endsWith("/comments"))?.body as { body: string }).body;
    expect(requests.some((q) => q.url === "/llm/chat/completions")).toBe(true);
    expect(body).toContain("💡 Why it matters");
    expect(body).toContain("Move the shared code to lib/.");
    expect(r.stdout).toContain("AI explanations: 2");
  });

  it("respects fail-on: none", async () => {
    const r = await runAction({ "FAIL-ON": "none" }, prEvent());
    expect(r.code).toBe(0);
  });

  it("warns instead of crashing when the token can't comment (fork PRs)", async () => {
    commentStatus = 403;
    const r = await runAction({ "FAIL-ON": "none" }, prEvent());
    expect(r.code).toBe(0);
    expect(r.stdout).toContain("::warning::Could not post the PR comment (the token is read-only");
  });

  it("only reports on push events and never fails", async () => {
    const r = await runAction({}, null, "push");
    expect(r.code).toBe(0);
    expect(requests).toHaveLength(0);
    expect(r.summary).toMatch(/Health \d+\/100/);
    expect(r.stdout).toContain("Not a pull request event (push)");
  });
});

import type { Metadata, Viewport } from "next";
import "@xyflow/react/dist/base.css";
import "./globals.css";
import "./dashboard.css";

export const metadata: Metadata = {
  title: "ArchGuard",
  description: "Explore a codebase's dependency graph, architecture violations and drift over time.",
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
};

// Applies the saved theme before first paint, so there is no light/dark flash.
const themeScript = `try{var t=localStorage.getItem("archguard-theme");if(t==="light"||t==="dark")document.documentElement.dataset.theme=t}catch(e){}`;

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeScript }} />
      </head>
      <body>{children}</body>
    </html>
  );
}

import { Dashboard } from "@/components/Dashboard";

export default function Page() {
  return <Dashboard />;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { isHistory, isReport, layerColors, projectName, type History, type Report } from "@/lib/model";
import type { IssueFilter } from "@/lib/layout";
import { EmptyState } from "./EmptyState";
import { GraphView } from "./GraphView";
import { HistoryView } from "./HistoryView";
import { Inspector } from "./Inspector";
import { IssuesTable } from "./IssuesTable";
import { Sidebar } from "./Sidebar";
import { ThemeToggle } from "./ThemeToggle";

type Tab = "graph" | "issues" | "history";

export function Dashboard() {
  const [report, setReport] = useState<Report | null>(null);
  const [history, setHistory] = useState<History | null>(null);
  const [tab, setTab] = useState<Tab>("graph");
  const [selected, setSelected] = useState<string | null>(null);
  const [issueFilter, setIssueFilter] = useState<IssueFilter>("all");
  const [cycleFocus, setCycleFocus] = useState<number | null>(null);
  const [hiddenLayers, setHiddenLayers] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [dragging, setDragging] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);

  const accept = useCallback((data: unknown, source: string) => {
    if (isReport(data)) {
      setReport(data);
      setSelected(null);
      setIssueFilter("all");
      setCycleFocus(null);
      setHiddenLayers(new Set());
      setTab((t) => (t === "history" ? "graph" : t));
      setError(null);
      return true;
    }
    if (isHistory(data)) {
      setHistory(data);
      setTab("history");
      setError(null);
      return true;
    }
    setError(`${source} isn't an ArchGuard report or history file. Create one with "archguard analyze" or "archguard history".`);
    return false;
  }, []);

  // On start-up, load data/report.json and data/history.json when `archguard dashboard`
  // serves them, or the files named in ?report= and ?history=.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const sources = [params.get("report") ?? "data/report.json", params.get("history") ?? "data/history.json"];
    if (params.get("demo") !== null) sources.splice(0, 2, "demo/report.json", "demo/history.json");
    Promise.all(
      sources.map((url) =>
        fetch(url)
          .then((r) => (r.ok ? r.json() : null))
          .catch(() => null),
      ),
    ).then(([r, h]) => {
      if (isReport(r)) setReport(r);
      if (isHistory(h)) {
        setHistory(h);
        if (!isReport(r)) setTab("history");
      }
      setLoading(false);
    });
  }, []);

  const openFiles = useCallback(
    async (files: FileList | File[]) => {
      for (const file of Array.from(files)) {
        try {
          accept(JSON.parse(await file.text()), file.name);
        } catch {
          setError(`${file.name} isn't valid JSON.`);
        }
      }
    },
    [accept],
  );

  const loadDemo = useCallback(async () => {
    try {
      const [r, h] = await Promise.all(["demo/report.json", "demo/history.json"].map((u) => fetch(u).then((x) => x.json())));
      accept(r, "The demo report");
      accept(h, "The demo history");
      setTab("graph");
    } catch {
      setError("Couldn't load the demo data. Open a report file instead.");
    }
  }, [accept]);

  const colors = useMemo(() => (report ? layerColors(report) : new Map()), [report]);

  // Opening a file from the issues table or an inspector link must show it in the graph,
  // so lift any filter that would hide it.
  const selectFile = useCallback(
    (id: string | null) => {
      setSelected(id);
      if (!id) return;
      setTab("graph");
      const node = report?.nodes.find((n) => n.id === id);
      if (node && hiddenLayers.has(node.layer ?? "(none)")) setHiddenLayers(new Set());
      setIssueFilter((f) => (f === "all" ? f : "all"));
      setCycleFocus(null);
    },
    [report, hiddenLayers],
  );

  const dropHandlers = {
    onDragOver: (e: React.DragEvent) => {
      e.preventDefault();
      setDragging(true);
    },
    onDragLeave: (e: React.DragEvent) => {
      if (e.currentTarget === e.target) setDragging(false);
    },
    onDrop: (e: React.DragEvent) => {
      e.preventDefault();
      setDragging(false);
      if (e.dataTransfer.files.length) openFiles(e.dataTransfer.files);
    },
  };

  const hiddenInput = (
    <input
      ref={fileInput}
      type="file"
      accept=".json,application/json"
      multiple
      className="visually-hidden"
      onChange={(e) => {
        if (e.target.files) openFiles(e.target.files);
        e.target.value = "";
      }}
    />
  );

  if (loading) {
    return <div className="app app--loading blueprint-grid" aria-busy="true" />;
  }

  if (!report && !history) {
    return (
      <div className="app" {...dropHandlers}>
        {hiddenInput}
        <EmptyState onChoose={() => fileInput.current?.click()} onDemo={loadDemo} error={error} dragging={dragging} />
      </div>
    );
  }

  const tabs: { id: Tab; label: string; disabled?: boolean }[] = [
    { id: "graph", label: "Graph", disabled: !report },
    { id: "issues", label: "Issues", disabled: !report },
    { id: "history", label: "History", disabled: !history },
  ];

  return (
    <div className={`app${dragging ? " app--dragging" : ""}`} {...dropHandlers}>
      {hiddenInput}
      <header className="topbar">
        <div className="brand">
          <Logo />
          <span>ArchGuard</span>
        </div>
        <nav className="tabs" aria-label="Views">
          {tabs.map((t) => (
            <button
              key={t.id}
              className="tab"
              aria-current={tab === t.id ? "page" : undefined}
              disabled={t.disabled}
              title={t.disabled ? (t.id === "history" ? "Open a history file to see drift over time" : "Open a report first") : undefined}
              onClick={() => setTab(t.id)}
            >
              {t.label}
            </button>
          ))}
        </nav>
        <div className="topbar__actions">
          <button className="btn" onClick={() => fileInput.current?.click()}>
            Open file
          </button>
          <ThemeToggle />
        </div>
      </header>

      {error && (
        <div className="banner" role="alert">
          {error}
          <button className="btn btn--ghost" onClick={() => setError(null)} aria-label="Dismiss">
            ✕
          </button>
        </div>
      )}

      <div className={`workspace workspace--${tab}${selected && tab === "graph" ? " workspace--inspecting" : ""}`}>
        {report && tab !== "history" && (
          <Sidebar
            report={report}
            colors={colors}
            issueFilter={issueFilter}
            onIssueFilter={(f) => {
              setIssueFilter(f);
              setCycleFocus(null);
            }}
            cycleFocus={cycleFocus}
            onCycleFocus={setCycleFocus}
            hiddenLayers={hiddenLayers}
            onToggleLayer={(name) =>
              setHiddenLayers((prev) => {
                const next = new Set(prev);
                if (next.has(name)) next.delete(name);
                else next.add(name);
                return next;
              })
            }
          />
        )}

        <main className="stage" aria-label={tab === "graph" ? "Dependency graph" : tab === "issues" ? "Issues" : "History"}>
          {tab === "graph" && report && (
            <GraphView
              report={report}
              colors={colors}
              issueFilter={issueFilter}
              cycleFocus={cycleFocus}
              hiddenLayers={hiddenLayers}
              selected={selected}
              onSelect={selectFile}
            />
          )}
          {tab === "issues" && report && <IssuesTable report={report} onSelectFile={selectFile} />}
          {tab === "history" && history && <HistoryView history={history} />}
        </main>

        {tab === "graph" && report && selected && (
          <Inspector report={report} colors={colors} fileId={selected} onSelect={selectFile} onClose={() => setSelected(null)} />
        )}
      </div>

      <footer className="statusbar">
        {report ? (
          <span>
            {projectName(report)}: {report.summary.files} files, {report.summary.edges} imports, analysed{" "}
            {new Date(report.meta.generatedAt).toLocaleString()}
          </span>
        ) : (
          <span>History only. Open a report to explore the graph.</span>
        )}
        {history && tab !== "history" && (
          <button className="linkish" onClick={() => setTab("history")}>
            {history.points.length} commits of history loaded
          </button>
        )}
      </footer>
    </div>
  );
}

function Logo() {
  // A shield drawn as a drafting mark: an outline with a node graph inside.
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true">
      <path d="M12 2.5 4 5.5v6c0 5 3.4 8.6 8 10 4.6-1.4 8-5 8-10v-6l-8-3Z" fill="none" stroke="currentColor" strokeWidth="1.6" />
      <circle cx="9" cy="10" r="1.6" fill="currentColor" />
      <circle cx="15" cy="10" r="1.6" fill="currentColor" />
      <circle cx="12" cy="15" r="1.6" fill="currentColor" />
      <path d="M9 10 12 15 15 10" fill="none" stroke="currentColor" strokeWidth="1.2" />
    </svg>
  );
}

"use client";

import {
  Background,
  BaseEdge,
  Controls,
  getBezierPath,
  Handle,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
  type EdgeProps,
  type Node,
  type NodeProps,
} from "@xyflow/react";
import { memo, useEffect, useMemo, useState } from "react";
import { buildGraph, FILE_NODE_LIMIT, type EdgeData, type FileNodeData, type FolderNodeData, type IssueFilter } from "@/lib/layout";
import { ISSUE_LABEL, type Report, type ViolationType } from "@/lib/model";

interface Props {
  report: Report;
  colors: Map<string | null, string>;
  issueFilter: IssueFilter;
  /** When set, only the files of this cycle are drawn. */
  cycleFocus: number | null;
  hiddenLayers: Set<string>;
  selected: string | null;
  onSelect: (id: string | null) => void;
}

export function GraphView(props: Props) {
  return (
    <ReactFlowProvider>
      <GraphInner {...props} />
    </ReactFlowProvider>
  );
}

function GraphInner({ report, colors, issueFilter, cycleFocus, hiddenLayers, selected, onSelect }: Props) {
  const large = report.nodes.length > FILE_NODE_LIMIT;
  const [mode, setMode] = useState<"files" | "folders">(large ? "folders" : "files");
  const [folderDepth, setFolderDepth] = useState(2);
  const [scope, setScope] = useState<string | null>(null);
  const [showTypeOnly, setShowTypeOnly] = useState(false);
  const [query, setQuery] = useState("");
  const flow = useReactFlow();

  // Reset view state when a different report is loaded.
  useEffect(() => {
    setMode(report.nodes.length > FILE_NODE_LIMIT ? "folders" : "files");
    setChosenMode(false);
    setScope(null);
    setQuery("");
  }, [report]);

  // A narrowed issue filter usually leaves few enough files to show individually.
  const [chosenMode, setChosenMode] = useState(false); // the user clicked Files/Folders themselves
  const effectiveMode = !chosenMode && issueFilter !== "all" && issueFilter !== "issues" && mode === "folders" && !scope ? "files" : mode;

  const onlyFiles = useMemo(
    () => (issueFilter === "circular-dependency" && cycleFocus !== null && report.cycles[cycleFocus] ? new Set(report.cycles[cycleFocus].files) : null),
    [issueFilter, cycleFocus, report],
  );
  const graph = useMemo(
    () => buildGraph(report, colors, { mode: effectiveMode, folderDepth, hiddenLayers, issueFilter, scope, showTypeOnly, onlyFiles }),
    [report, colors, effectiveMode, folderDepth, hiddenLayers, issueFilter, scope, showTypeOnly, onlyFiles],
  );

  // Neighbourhood of the selected file: it and its direct imports/importers stay bright.
  const focus = useMemo(() => {
    if (!selected || effectiveMode !== "files") return null;
    const ids = new Set([selected]);
    for (const e of graph.edges) {
      if (e.source === selected) ids.add(e.target);
      if (e.target === selected) ids.add(e.source);
    }
    return ids;
  }, [selected, graph.edges, effectiveMode]);

  const q = query.trim().toLowerCase();
  const nodes = useMemo(
    () =>
      graph.nodes.map((n) => {
        const dim = (focus && !focus.has(n.id)) || (q && !n.id.toLowerCase().includes(q));
        return { ...n, selected: n.id === selected, className: dim ? "is-dim" : undefined };
      }),
    [graph.nodes, focus, q, selected],
  );
  const edges = useMemo(
    () =>
      graph.edges.map((e) => {
        const dim = focus ? !(e.source === selected || e.target === selected) : false;
        return { ...e, className: dim ? "is-dim" : undefined, zIndex: e.data?.cycle || e.data?.violation ? 1 : 0 };
      }),
    [graph.edges, focus, selected],
  );

  // Re-frame the drawing whenever the set of visible nodes changes.
  const signature = `${effectiveMode}|${folderDepth}|${scope}|${issueFilter}|${cycleFocus}|${[...hiddenLayers].join(",")}|${graph.nodes.length}`;
  useEffect(() => {
    const t = setTimeout(() => flow.fitView({ padding: 0.12, duration: 300, maxZoom: 1.2 }), 30);
    return () => clearTimeout(t);
  }, [signature, flow]);

  // Center on a file selected from elsewhere (search result, issue table, inspector link).
  useEffect(() => {
    if (!selected || effectiveMode !== "files") return;
    const n = graph.nodes.find((x) => x.id === selected);
    if (n) flow.setCenter(n.position.x + 98, n.position.y + 23, { zoom: Math.max(flow.getZoom(), 0.9), duration: 300 });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected]);

  const searchHits = q ? graph.nodes.filter((n) => n.id.toLowerCase().includes(q)) : [];

  return (
    <div className="graph">
      <EdgeMarkers />
      <div className="graph__toolbar" role="toolbar" aria-label="Graph view options">
        <div className="segmented" role="radiogroup" aria-label="Group by">
          <button role="radio" aria-checked={effectiveMode === "files"} onClick={() => { setChosenMode(true); setMode("files"); }}>
            Files
          </button>
          <button role="radio" aria-checked={effectiveMode === "folders"} onClick={() => { setChosenMode(true); setMode("folders"); onSelect(null); }}>
            Folders
          </button>
        </div>
        {effectiveMode === "folders" && (
          <label className="field">
            <span>Depth</span>
            <select value={folderDepth} onChange={(e) => setFolderDepth(Number(e.target.value))}>
              {[1, 2, 3, 4].map((d) => (
                <option key={d} value={d}>
                  {d}
                </option>
              ))}
            </select>
          </label>
        )}
        <label className="check">
          <input type="checkbox" checked={showTypeOnly} onChange={(e) => setShowTypeOnly(e.target.checked)} />
          Type-only imports
        </label>
        <div className="search">
          <input
            type="search"
            placeholder="Find a file"
            aria-label="Find a file"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && searchHits[0]) {
                if (effectiveMode === "files") onSelect(searchHits[0].id);
                else flow.setCenter(searchHits[0].position.x + 108, searchHits[0].position.y + 29, { zoom: 1, duration: 300 });
              }
            }}
          />
          {q && <span className="search__count">{searchHits.length} found</span>}
        </div>
      </div>

      {scope && (
        <div className="scope-bar">
          Showing <span className="mono">{scope}/</span>
          <button className="btn btn--small" onClick={() => { setScope(null); setMode("folders"); onSelect(null); }}>
            Back to all folders
          </button>
        </div>
      )}

      {graph.tooLarge && effectiveMode === "files" && (
        <div className="scope-bar scope-bar--warn">
          {graph.nodes.length} files is a lot to draw at once. The folder view, or an issue filter, is easier to read.
          <button className="btn btn--small" onClick={() => setMode("folders")}>
            Group by folder
          </button>
        </div>
      )}

      <div className="graph__canvas blueprint-grid">
        {graph.nodes.length === 0 ? (
          <div className="graph__empty">
            <p>No files match these filters.</p>
          </div>
        ) : (
          <ReactFlow
            nodes={nodes}
            edges={edges}
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            onNodeClick={(_, n: Node) => {
              if (effectiveMode === "files") {
                onSelect(n.id === selected ? null : n.id);
              } else {
                setScope(n.id === "(root)" ? null : n.id);
                setMode("files");
                setChosenMode(true);
              }
            }}
            onPaneClick={() => onSelect(null)}
            nodesDraggable={false}
            nodesConnectable={false}
            edgesFocusable={false}
            onlyRenderVisibleElements
            minZoom={0.05}
            maxZoom={2}
            proOptions={{ hideAttribution: true }}
          >
            <Background gap={24} size={0} color="transparent" />
            <Controls showInteractive={false} position="bottom-left" />
            <MiniMap
              pannable
              zoomable
              position="bottom-right"
              nodeColor={(n) => {
                const d = n.data as FileNodeData | FolderNodeData;
                const critical = d.kind === "file" ? d.issues.includes("circular-dependency") : !!d.issueCounts["circular-dependency"];
                return critical ? "var(--critical)" : "var(--ink-2)";
              }}
              nodeBorderRadius={2}
              nodeStrokeWidth={0}
              maskColor="var(--minimap-mask)"
              ariaLabel="Overview of the whole graph"
            />
          </ReactFlow>
        )}
      </div>

      <GraphLegend mode={effectiveMode} />
    </div>
  );
}

function GraphLegend({ mode }: { mode: "files" | "folders" }) {
  return (
    <div className="graph-legend" aria-label="Legend">
      <span className="legend-item">
        <svg width="26" height="8" aria-hidden="true"><line x1="0" y1="4" x2="26" y2="4" className="legend-edge" /></svg>
        imports
      </span>
      <span className="legend-item">
        <svg width="26" height="8" aria-hidden="true"><line x1="0" y1="4" x2="26" y2="4" className="legend-edge legend-edge--cycle" /></svg>
        <span className="tone-critical" aria-hidden="true">⟲</span> part of a cycle
      </span>
      <span className="legend-item">
        <svg width="26" height="8" aria-hidden="true"><line x1="0" y1="4" x2="26" y2="4" className="legend-edge legend-edge--violation" /></svg>
        <span className="tone-serious" aria-hidden="true">⚠</span> breaks a layer rule
      </span>
      <span className="legend-hint">
        {mode === "folders" ? "Click a folder to open it." : "Click a file to inspect it."} Arrows point from a file to what it imports.
      </span>
    </div>
  );
}

const IssueBadges = ({ types }: { types: ViolationType[] }) =>
  types.length ? (
    <span className="badges">
      {types.map((t) => (
        <span key={t} className={`issue-icon tone-${ISSUE_LABEL[t].tone}`} title={ISSUE_LABEL[t].one} aria-label={ISSUE_LABEL[t].one} role="img">
          {ISSUE_LABEL[t].icon}
        </span>
      ))}
    </span>
  ) : null;

const FileNode = memo(function FileNode({ data, selected }: NodeProps<Node<FileNodeData>>) {
  const critical = data.issues.includes("circular-dependency");
  return (
    <div className={`gnode${selected ? " gnode--selected" : ""}${critical ? " gnode--critical" : ""}`} style={{ "--layer": data.color } as React.CSSProperties}>
      <Handle type="target" position={Position.Left} className="ghandle" />
      <span className="gnode__stripe" aria-hidden="true" />
      <span className="gnode__body">
        <span className="gnode__name mono">{data.label}</span>
        <span className="gnode__meta">
          <span className="gnode__layer">{data.layer ?? "no layer"}</span>
          <span className="gnode__dir mono">{data.dir}</span>
        </span>
      </span>
      <IssueBadges types={data.issues} />
      <Handle type="source" position={Position.Right} className="ghandle" />
    </div>
  );
});

const FolderNode = memo(function FolderNode({ data }: NodeProps<Node<FolderNodeData>>) {
  const types = (Object.keys(data.issueCounts) as ViolationType[]).filter((t) => (data.issueCounts[t] ?? 0) > 0);
  return (
    <div className={`gnode gnode--folder${data.issueCounts["circular-dependency"] ? " gnode--critical" : ""}`} style={{ "--layer": data.color } as React.CSSProperties}>
      <Handle type="target" position={Position.Left} className="ghandle" />
      <span className="gnode__stripe" aria-hidden="true" />
      <span className="gnode__body">
        <span className="gnode__name mono">{data.label}/</span>
        <span className="gnode__meta">
          <span className="gnode__layer">{data.files} {data.files === 1 ? "file" : "files"}</span>
          {types.map((t) => (
            <span key={t} className={`folder-issue tone-${ISSUE_LABEL[t].tone}`} title={`${data.issueCounts[t]} ${ISSUE_LABEL[t].many.toLowerCase()}`}>
              {ISSUE_LABEL[t].icon} {data.issueCounts[t]}
            </span>
          ))}
        </span>
      </span>
      <Handle type="source" position={Position.Right} className="ghandle" />
    </div>
  );
});

function DepEdge({ id, sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition, data }: EdgeProps & { data?: EdgeData }) {
  const [path] = getBezierPath({ sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition });
  const kind = data?.cycle ? "cycle" : data?.violation ? "violation" : "plain";
  const width = data && data.weight > 1 ? Math.min(1.25 + Math.log2(data.weight) * 0.6, 4.5) : undefined;
  return (
    <BaseEdge
      id={id}
      path={path}
      className={`gedge gedge--${kind}${data?.typeOnly ? " gedge--type" : ""}`}
      markerEnd={`url(#arrow-${kind})`}
      style={width ? { strokeWidth: width } : undefined}
    />
  );
}

const nodeTypes = { file: FileNode, folder: FolderNode };
const edgeTypes = { dep: DepEdge };

/** Arrowheads in the three edge colours; rendered once and referenced by id. */
export function EdgeMarkers() {
  return (
    <svg className="visually-hidden" aria-hidden="true">
      <defs>
        {["plain", "cycle", "violation"].map((k) => (
          <marker key={k} id={`arrow-${k}`} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
            <path d="M0,1 L9,5 L0,9 Z" className={`arrowhead arrowhead--${k}`} />
          </marker>
        ))}
      </defs>
    </svg>
  );
}

