/** @type {import('next').NextConfig} */
const nextConfig = {
  // Static export: the dashboard is plain HTML/JS/CSS that can be opened from
  // `archguard dashboard`, any static host, or GitHub Pages. No server needed.
  output: "export",
  images: { unoptimized: true },
  trailingSlash: true,
};

export default nextConfig;

import type { Explanation, History, Report, ReportDiff, Violation } from "@archguard/core";

const useColor = !process.env.NO_COLOR && process.stdout.isTTY && !process.argv.includes("--no-color");
const wrap = (code: number) => (s: string | number) => (useColor ? `\x1b[${code}m${s}\x1b[0m` : String(s));

export const c = {
  bold: wrap(1),
  dim: wrap(2),
  red: wrap(31),
  green: wrap(32),
  yellow: wrap(33),
  blue: wrap(34),
  magenta: wrap(35),
  cyan: wrap(36),
};

const gradeColor = (grade: string) => (grade === "A" || grade === "B" ? c.green : grade === "C" ? c.yellow : c.red);

function section(title: string, count: number, color: (s: string | number) => string): string {
  return `\n${c.bold(title)} ${color(`(${count})`)}`;
}

function list<T>(items: T[], limit: number, render: (item: T) => string): string[] {
  const lines = items.slice(0, limit).map(render);
  if (items.length > limit) lines.push(c.dim(`  … and ${items.length - limit} more (see the JSON report)`));
  return lines;
}

/** Human-readable terminal report. */
export function formatReport(report: Report, limit: number): string {
  const { summary, score } = report;
  const byType = (t: Violation["type"]) => report.violations.filter((v) => v.type === t);
  const out: string[] = [];

  out.push("");
  out.push(`${c.bold(c.cyan("ArchGuard"))} ${c.dim(`v${report.meta.version}`)}  ${c.dim(report.meta.root)}`);
  out.push(c.dim(`config: ${report.meta.configSource} · aliases: ${report.meta.tsconfig ?? "none"} · ${report.meta.durationMs} ms`));
  out.push("");
  out.push(
    `${c.bold("Health")} ${gradeColor(score.grade)(c.bold(`${score.health}/100`))} ${gradeColor(score.grade)(`grade ${score.grade}`)}` +
      c.dim(`   (${score.driftPoints} drift points across ${summary.files} files)`),
  );
  out.push(
    `${summary.files} files · ${summary.edges} internal imports · ${summary.externalPackages} external packages` +
      (summary.unresolved ? ` · ${c.yellow(`${summary.unresolved} unresolved`)}` : "") +
      (summary.ignoredImports ? c.dim(` · ${summary.ignoredImports} imports of excluded files`) : ""),
  );

  const layers = report.layers.filter((l) => l.files > 0);
  if (layers.length) out.push(c.dim(`layers: ${layers.map((l) => `${l.name} ${l.files}`).join(" · ")}`));

  const cycles = report.cycles;
  out.push(section("Circular dependencies", cycles.length, cycles.length ? c.red : c.green));
  if (!cycles.length) out.push(c.green("  ✓ none"));
  out.push(
    ...list(cycles, limit, (cy) => {
      const head = `  ${c.red("✗")} ${cy.files.length} file${cy.files.length > 1 ? "s" : ""}: `;
      return head + cy.path.map((p, i) => (i === cy.path.length - 1 ? c.dim(p) : p)).join(c.dim(" → "));
    }),
  );

  const layerV = byType("layer-violation");
  out.push(section("Layer violations", layerV.length, layerV.length ? c.red : c.green));
  if (!layerV.length) out.push(c.green("  ✓ none"));
  out.push(...list(layerV, limit, (v) => `  ${c.red("✗")} ${c.magenta(v.rule ?? "")}  ${v.file}:${v.line} ${c.dim("→")} ${v.target}`));

  const god = byType("god-file");
  out.push(section("God files", god.length, god.length ? c.yellow : c.green));
  if (!god.length) out.push(c.green("  ✓ none"));
  out.push(...list(god, limit, (v) => `  ${c.yellow("!")} ${v.message.replace(/ Consider splitting.*$/, "")}`));

  const top = [...report.nodes].sort((a, b) => b.fanIn + b.fanOut - (a.fanIn + a.fanOut)).slice(0, 5).filter((n) => n.fanIn + n.fanOut > 0);
  if (top.length) {
    out.push(`\n${c.bold("Most coupled files")}`);
    out.push(c.dim(`  ${"fan-in".padStart(6)} ${"fan-out".padStart(7)} ${"instab.".padStart(7)}  file`));
    for (const n of top) {
      out.push(`  ${String(n.fanIn).padStart(6)} ${String(n.fanOut).padStart(7)} ${n.instability.toFixed(2).padStart(7)}  ${n.id}`);
    }
  }

  const orphans = byType("orphan-file");
  if (orphans.length) {
    out.push(section("Possibly unused files", orphans.length, c.blue));
    out.push(...list(orphans, limit, (v) => `  ${c.blue("·")} ${v.file}`));
  }

  if (report.unresolved.length) {
    out.push(section("Unresolved imports", report.unresolved.length, c.yellow));
    out.push(...list(report.unresolved, limit, (u) => `  ${c.yellow("?")} ${u.from}:${u.line} ${c.dim("→")} ${u.specifier}`));
  }

  out.push("");
  return out.join("\n");
}

/** Terminal view of a git-history analysis, with a bar per commit. */
export function formatHistory(history: History, limit: number): string {
  const out: string[] = [""];
  const { points, trend, meta } = history;
  out.push(`${c.bold(c.cyan("ArchGuard history"))} ${c.dim(`${meta.repo}${meta.subpath !== "." ? `/${meta.subpath}` : ""}`)}`);
  out.push(c.dim(`${points.length} commits (${meta.strategy}) · ${meta.durationMs} ms · config: ${meta.configSource}`));
  out.push("");
  out.push(c.dim(`  ${"commit".padEnd(9)} ${"date".padEnd(10)} ${"health".padStart(6)}  ${"".padEnd(20)} ${"cyc".padStart(3)} ${"lay".padStart(3)} ${"god".padStart(3)} ${"files".padStart(5)}  message`));

  let prev: number | null = null;
  for (const p of points) {
    if (!p.analyzed) {
      out.push(c.dim(`  ${p.shortSha.padEnd(9)} ${p.date.slice(0, 10)}      –  (no source files at this commit)  ${p.message.slice(0, 50)}`));
      continue;
    }
    const bar = "█".repeat(Math.round(p.health / 5)).padEnd(20, "·");
    const color = gradeColor(p.grade);
    const change = prev === null || p.health === prev ? " " : p.health > prev ? c.green("▲") : c.red("▼");
    out.push(
      `  ${p.shortSha.padEnd(9)} ${p.date.slice(0, 10)} ${color(String(p.health).padStart(6))}${change} ${color(bar)} ` +
        `${String(p.cycles).padStart(3)} ${String(p.layerViolations).padStart(3)} ${String(p.godFiles).padStart(3)} ${String(p.files).padStart(5)}  ${p.message.slice(0, 60)}`,
    );
    prev = p.health;
  }

  if (trend.delta !== null) {
    const d = trend.delta;
    out.push("");
    out.push(`${c.bold("Trend")} ${trend.firstHealth} → ${trend.lastHealth} ${d > 0 ? c.green(`(+${d}, improving)`) : d < 0 ? c.red(`(${d}, drifting)`) : c.dim("(stable)")}`);
  }
  if (trend.regressions.length) {
    out.push(`\n${c.bold("Biggest regressions")}`);
    out.push(...trend.regressions.slice(0, limit).map((r) => `  ${c.red(String(r.delta).padStart(4))}  ${r.to}  ${r.message}`));
  }
  if (trend.improvements.length) {
    out.push(`\n${c.bold("Biggest improvements")}`);
    out.push(...trend.improvements.slice(0, limit).map((r) => `  ${c.green(`+${r.delta}`.padStart(4))}  ${r.to}  ${r.message}`));
  }
  out.push("");
  return out.join("\n");
}

/** Terminal view of a base vs head comparison. */
export function formatDiff(base: Report, head: Report, diff: ReportDiff, limit: number, explanations?: Map<string, Explanation>): string {
  const out: string[] = [""];
  const d = diff.healthDelta;
  out.push(`${c.bold(c.cyan("ArchGuard diff"))}  health ${base.score.health} → ${head.score.health} ${d > 0 ? c.green(`(+${d})`) : d < 0 ? c.red(`(${d})`) : c.dim("(no change)")}`);
  out.push(section("Introduced", diff.introduced.length, diff.introduced.length ? c.red : c.green));
  if (!diff.introduced.length) out.push(c.green("  ✓ no new issues"));
  for (const v of diff.introduced.slice(0, limit)) {
    out.push(`  ${v.severity === "error" ? c.red("✗") : v.severity === "warning" ? c.yellow("!") : c.blue("·")} ${v.message}`);
    const e = explanations?.get(v.key);
    if (e) out.push(c.dim(`      why: ${e.explanation}`), c.dim(`      fix: ${e.suggestion}`));
  }
  if (diff.introduced.length > limit) out.push(c.dim(`  … and ${diff.introduced.length - limit} more`));
  out.push(section("Resolved", diff.resolved.length, c.green));
  for (const v of diff.resolved.slice(0, limit)) out.push(`  ${c.green("✓")} ${v.message}`);
  out.push("");
  return out.join("\n");
}

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import {
  analyze, analyzeHistory, CONFIG_FILENAME, createExplainer, DEFAULT_CONFIG, diffReports, renderPrComment, VERSION,
  type Report,
} from "@archguard/core";
import { c, formatDiff, formatHistory, formatReport } from "./format.js";

const HELP = `
${c.bold("archguard")}: architecture drift detection for JS/TS codebases

${c.bold("Usage")}
  archguard analyze [path]            Analyse a project (default: current directory)
  archguard history [path]            Score past git commits to show drift over time
  archguard diff <base.json> <head.json>  Compare two reports (e.g. main vs a branch)
  archguard init [path]               Write a starter ${CONFIG_FILENAME}

${c.bold("Common options")}
  -c, --config <file>     Config file (default: <path>/${CONFIG_FILENAME}, else Next.js preset)
  -o, --out <file>        Where to write JSON output
      --json              Print JSON to stdout instead of the summary
      --limit <n>         Max items listed per section (default: 10)
      --no-color          Disable colours
  -h, --help · -v, --version

${c.bold("analyze")}
      --no-report         Don't write archguard-report.json
      --fail-on <level>   Exit 1 if issues at this level exist: error | warning | none (default: error)

${c.bold("history")}
      --commits <n>       Number of commits to analyse (default: 30)
      --spread            Spread the commits evenly over the whole history (default: the latest n)
      --ref <ref>         Branch/tag/commit to walk back from (default: HEAD)

${c.bold("diff")}
      --markdown          Print the GitHub pull-request comment instead of the terminal summary
      --explain           Add AI explanations (needs OPENAI_API_KEY; optional OPENAI_MODEL, OPENAI_BASE_URL)
      --root <path>       Project folder for --explain code context (default: head report's root)
      --fail-on <level>   Exit 1 if NEW issues at this level exist (default: error)

${c.bold("Exit codes")}  0 = passed · 1 = issues at --fail-on level · 2 = could not run
`;

type FailOn = "error" | "warning" | "none";

interface Args {
  command: string;
  positional: string[];
  config?: string;
  out?: string;
  writeReport: boolean;
  json: boolean;
  failOn: FailOn;
  limit: number;
  commits: number;
  spread: boolean;
  ref?: string;
  markdown: boolean;
  explain: boolean;
  root?: string;
}

function parseArgs(argvIn: string[]): Args {
  const args: Args = {
    command: "", positional: [], writeReport: true, json: false, failOn: "error", limit: 10,
    commits: 30, spread: false, markdown: false, explain: false,
  };
  // Accept both "--limit 5" and "--limit=5".
  const argv = argvIn.flatMap((a) => (/^--[a-z-]+=/.test(a) ? [a.slice(0, a.indexOf("=")), a.slice(a.indexOf("=") + 1)] : [a]));

  const value = (i: number, flag: string) => {
    const v = argv[i + 1];
    if (v === undefined || v.startsWith("-")) throw new Error(`${flag} needs a value`);
    return v;
  };
  const positiveInt = (v: string, flag: string) => {
    const n = Number(v);
    if (!Number.isInteger(n) || n < 1) throw new Error(`${flag} must be a positive integer`);
    return n;
  };

  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    switch (a) {
      case "-h": case "--help": args.command = "help"; break;
      case "-v": case "--version": args.command = "version"; break;
      case "-c": case "--config": args.config = value(i, a); i++; break;
      case "-o": case "--out": args.out = value(i, a); i++; break;
      case "--root": args.root = value(i, a); i++; break;
      case "--ref": args.ref = value(i, a); i++; break;
      case "--no-report": args.writeReport = false; break;
      case "--json": args.json = true; break;
      case "--spread": args.spread = true; break;
      case "--markdown": args.markdown = true; break;
      case "--explain": args.explain = true; break;
      case "--no-color": break; // handled in format.ts
      case "--fail-on": {
        const v = value(i, a); i++;
        if (v !== "error" && v !== "warning" && v !== "none") throw new Error(`--fail-on must be error, warning or none`);
        args.failOn = v;
        break;
      }
      case "--limit": args.limit = positiveInt(value(i, a), a); i++; break;
      case "--commits": args.commits = positiveInt(value(i, a), a); i++; break;
      default:
        if (a.startsWith("-")) throw new Error(`Unknown option: ${a}`);
        args.positional.push(a);
    }
  }

  if (!args.command) args.command = args.positional.shift() ?? "help";
  const maxPositional = args.command === "diff" ? 2 : 1;
  if (args.positional.length > maxPositional) {
    throw new Error(`Too many arguments for "${args.command}": ${args.positional.join(" ")}`);
  }
  return args;
}

const failsAt = (severities: string[], failOn: FailOn) =>
  failOn !== "none" && severities.some((s) => s === "error" || (failOn === "warning" && s === "warning"));

function writeJson(file: string, data: unknown): string {
  const abs = path.resolve(file);
  fs.writeFileSync(abs, JSON.stringify(data, null, 2));
  return path.relative(process.cwd(), abs) || abs;
}

async function runAnalyze(args: Args): Promise<number> {
  const root = path.resolve(args.positional[0] ?? ".");
  const report = await analyze(root, { configPath: args.config });

  // An empty analysis must never pass CI with a perfect score.
  if (report.summary.files === 0) {
    console.error(c.yellow(`No source files found in ${root}. Check the path and the "include"/"exclude" settings.`));
    return 2;
  }

  // The report file is written by default, or whenever --out is given; --json alone only prints.
  const writeFile = args.out !== undefined || (args.writeReport && !args.json);
  const written = writeFile ? writeJson(args.out ?? path.join(root, "archguard-report.json"), report) : null;

  if (args.json) {
    process.stdout.write(JSON.stringify(report, null, 2) + "\n");
  } else {
    console.log(formatReport(report, args.limit));
    if (written) console.log(c.dim(`JSON report written to ${written}`));
  }

  const failed = failsAt(report.violations.map((v) => v.severity), args.failOn);
  if (!args.json) console.log(failed ? c.red(`\n✗ Failed (--fail-on ${args.failOn})`) : c.green("\n✓ Passed"));
  return failed ? 1 : 0;
}

async function runHistory(args: Args): Promise<number> {
  const root = path.resolve(args.positional[0] ?? ".");
  const showProgress = !args.json && process.stderr.isTTY;
  const history = await analyzeHistory(root, {
    commits: args.commits,
    strategy: args.spread ? "spread" : "latest",
    ref: args.ref,
    configPath: args.config,
    onProgress: showProgress ? (done, total, sha) => process.stderr.write(`\r${c.dim(`analysing commit ${done + 1 > total ? total : done + 1}/${total} ${sha}   `)}`) : undefined,
  });
  if (showProgress) process.stderr.write("\r\x1b[K");

  const written = writeJson(args.out ?? path.join(root, "archguard-history.json"), history);
  if (args.json) {
    process.stdout.write(JSON.stringify(history, null, 2) + "\n");
  } else {
    console.log(formatHistory(history, args.limit));
    console.log(c.dim(`History written to ${written}. Open it in the ArchGuard dashboard to see the chart.`));
  }
  return 0;
}

async function runDiff(args: Args): Promise<number> {
  if (args.positional.length !== 2) throw new Error("diff needs two report files: archguard diff <base.json> <head.json>");
  const [base, head] = args.positional.map((f) => JSON.parse(fs.readFileSync(path.resolve(f), "utf8")) as Report);
  for (const r of [base, head]) {
    if (r?.meta?.tool !== "archguard" || !Array.isArray(r.violations)) throw new Error("Both files must be ArchGuard reports (archguard-report.json)");
  }
  const diff = diffReports(base, head);

  let explanations;
  if (args.explain) {
    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) {
      console.error(c.yellow("--explain needs the OPENAI_API_KEY environment variable; continuing without explanations."));
    } else {
      try {
        const explainer = createExplainer({ provider: "openai", apiKey, model: process.env.OPENAI_MODEL, baseUrl: process.env.OPENAI_BASE_URL });
        explanations = await explainer.explain(diff.introduced, head, path.resolve(args.root ?? head.meta.root));
      } catch (err) {
        console.error(c.yellow(`AI explanations failed (${(err as Error).message}); continuing without them.`));
      }
    }
  }

  if (args.json) process.stdout.write(JSON.stringify({ ...diff, explanations: explanations ? Object.fromEntries(explanations) : undefined }, null, 2) + "\n");
  else if (args.markdown) process.stdout.write(renderPrComment(base, head, diff, { explanations, limit: args.limit }) + "\n");
  else console.log(formatDiff(base, head, diff, args.limit, explanations));

  if (args.out) writeJson(args.out, diff);
  return failsAt(diff.introduced.map((v) => v.severity), args.failOn) ? 1 : 0;
}

function runInit(args: Args): number {
  const file = path.join(path.resolve(args.positional[0] ?? "."), CONFIG_FILENAME);
  if (fs.existsSync(file)) {
    console.error(c.yellow(`${file} already exists, so it was not overwritten.`));
    return 2;
  }
  const { layers, rules, thresholds, ignoreTypeOnlyImports, reportOrphans } = DEFAULT_CONFIG;
  fs.writeFileSync(file, JSON.stringify({ exclude: [], layers, rules, thresholds, ignoreTypeOnlyImports, reportOrphans }, null, 2) + "\n");
  console.log(c.green(`✓ Created ${file}`));
  console.log(c.dim("Edit the layers and rules to match your project, then run: archguard analyze"));
  return 0;
}

async function main(): Promise<number> {
  let args: Args;
  try {
    args = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error(c.red(`Error: ${(err as Error).message}`));
    console.error(HELP);
    return 2;
  }

  switch (args.command) {
    case "help": console.log(HELP); return 0;
    case "version": console.log(VERSION); return 0;
    case "analyze": return runAnalyze(args);
    case "history": return runHistory(args);
    case "diff": return runDiff(args);
    case "init": return runInit(args);
    default:
      console.error(c.red(`Unknown command: ${args.command}`));
      console.error(HELP);
      return 2;
  }
}

main().then(
  (code) => { process.exitCode = code; },
  (err) => {
    console.error(c.red(`Error: ${(err as Error).message}`));
    process.exitCode = 2;
  },
);

