import fs from "node:fs";
import path from "node:path";
import fg from "fast-glob";
import { ALWAYS_EXCLUDE, OUTPUT_DIRS } from "./config.js";
import type { ArchGuardConfig } from "./types.js";

/**
 * Finds every source file in the project that should become a graph node.
 * Returns POSIX paths relative to `root`, sorted for deterministic output.
 */
export async function discoverFiles(root: string, config: ArchGuardConfig): Promise<string[]> {
  const files = await fg(config.include, {
    cwd: root,
    ignore: [...ALWAYS_EXCLUDE, ...config.exclude],
    dot: false,
    onlyFiles: true,
    followSymbolicLinks: false,
  });
  const isOutput = createOutputDirCheck(root);
  return files.filter((f) => !isOutput(f)).sort();
}

/**
 * Returns a predicate telling whether a file lives inside a build-output folder
 * (dist/, build/, out/, coverage/) that sits next to a package.json. Those hold
 * compiled copies of the source and would duplicate every module in the graph,
 * whereas a folder like src/lib/build/ is real source and is kept.
 */
function createOutputDirCheck(root: string): (file: string) => boolean {
  const cache = new Map<string, boolean>();
  const hasPackageJson = (dir: string) => {
    if (!cache.has(dir)) cache.set(dir, fs.existsSync(path.join(root, dir, "package.json")));
    return cache.get(dir)!;
  };

  return (file) => {
    const parts = file.split("/");
    for (let i = 0; i < parts.length - 1; i++) {
      if (OUTPUT_DIRS.includes(parts[i]) && hasPackageJson(parts.slice(0, i).join("/"))) return true;
    }
    return false;
  };
}

import ts from "typescript";
import type { ImportKind, RawImport } from "./types.js";

/** Picks the TypeScript parser mode from the file extension. */
function scriptKindFor(fileName: string): ts.ScriptKind {
  if (fileName.endsWith(".tsx")) return ts.ScriptKind.TSX;
  if (fileName.endsWith(".jsx")) return ts.ScriptKind.JSX;
  if (/\.(m|c)?js$/.test(fileName)) return ts.ScriptKind.JS;
  return ts.ScriptKind.TS;
}

/**
 * Extracts every module reference from one file's source text.
 *
 * We parse the file into an Abstract Syntax Tree with the TypeScript compiler
 * (which also understands plain JavaScript and JSX), then walk the tree looking
 * for the node types that reference other modules. Working on the AST instead
 * of using regular expressions means comments, strings that merely *look* like
 * imports, and unusual formatting cannot fool us.
 */
export function extractImports(fileName: string, sourceText: string): RawImport[] {
  const sf = ts.createSourceFile(fileName, sourceText, ts.ScriptTarget.Latest, true, scriptKindFor(fileName));
  const found: RawImport[] = [];
  // If the file defines its own `require` (variable, function or parameter),
  // calls to it are not CommonJS imports. A whole-file check is a deliberate
  // simplification of real scope analysis; local `require` shadowing is rare.
  const requireIsShadowed = declaresName(sf, "require");

  const add = (node: ts.Node, specifier: string, kind: ImportKind, typeOnly: boolean) => {
    const { line } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
    found.push({ specifier, kind, typeOnly, line: line + 1 });
  };

  const visit = (node: ts.Node): void => {
    // import x from "./x";  import { a, type B } from "./x";  import type T from "./x";  import "./x";
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
      const clause = node.importClause;
      if (!clause) {
        add(node, node.moduleSpecifier.text, "side-effect", false);
      } else {
        add(node, node.moduleSpecifier.text, "static", isTypeOnlyImportClause(clause));
      }
    }

    // export * from "./x";  export { a } from "./x";  export type { T } from "./x";
    else if (ts.isExportDeclaration(node) && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      add(node, node.moduleSpecifier.text, "re-export", node.isTypeOnly || isTypeOnlyExportClause(node));
    }

    // import x = require("./x");
    else if (
      ts.isImportEqualsDeclaration(node) &&
      ts.isExternalModuleReference(node.moduleReference) &&
      ts.isStringLiteral(node.moduleReference.expression)
    ) {
      add(node, node.moduleReference.expression.text, "import-equals", node.isTypeOnly);
    }

    // type T = import("./x").T
    else if (
      ts.isImportTypeNode(node) &&
      ts.isLiteralTypeNode(node.argument) &&
      ts.isStringLiteral(node.argument.literal)
    ) {
      add(node, node.argument.literal.text, "import-type", true);
    }

    // import("./x")  and  require("./x")
    else if (ts.isCallExpression(node) && node.arguments.length >= 1) {
      const arg = node.arguments[0];
      const literal = ts.isStringLiteral(arg) || ts.isNoSubstitutionTemplateLiteral(arg) ? arg.text : null;
      if (literal !== null) {
        if (node.expression.kind === ts.SyntaxKind.ImportKeyword) {
          add(node, literal, "dynamic", false);
        } else if (ts.isIdentifier(node.expression) && node.expression.text === "require" && !requireIsShadowed) {
          add(node, literal, "require", false);
        }
      }
    }

    ts.forEachChild(node, visit);
  };

  visit(sf);
  return found;
}

/** True if the file declares a variable, function, parameter or import binding called `name`. */
function declaresName(sf: ts.SourceFile, name: string): boolean {
  if (!sf.text.includes(name)) return false;
  let found = false;
  const visit = (node: ts.Node): void => {
    if (found) return;
    if (
      (ts.isVariableDeclaration(node) || ts.isFunctionDeclaration(node) || ts.isParameter(node) ||
        ts.isImportSpecifier(node) || ts.isImportClause(node)) &&
      node.name && ts.isIdentifier(node.name) && node.name.text === name
    ) {
      // `const require = createRequire(import.meta.url)` is the ESM way to get a REAL require.
      const isCreateRequire =
        ts.isVariableDeclaration(node) && node.initializer && ts.isCallExpression(node.initializer) &&
        /createRequire$/.test(node.initializer.expression.getText(sf));
      if (!isCreateRequire) {
        found = true;
        return;
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return found;
}

/** `import type X` or `import { type A, type B }` (every binding is type-only). */
function isTypeOnlyImportClause(clause: ts.ImportClause): boolean {
  if (clause.isTypeOnly) return true;
  if (clause.name) return false; // a default value import
  const bindings = clause.namedBindings;
  if (!bindings) return false;
  if (ts.isNamespaceImport(bindings)) return false;
  return bindings.elements.length > 0 && bindings.elements.every((el) => el.isTypeOnly);
}

/** `export { type A, type B } from "./x"`. */
function isTypeOnlyExportClause(node: ts.ExportDeclaration): boolean {
  const clause = node.exportClause;
  if (!clause || !ts.isNamedExports(clause)) return false;
  return clause.elements.length > 0 && clause.elements.every((el) => el.isTypeOnly);
}

import type { Edge } from "./types.js";

/**
 * A directed graph of files. An edge A -> B means "A imports B".
 *
 * Stored as an adjacency list (Map from node to the set of its successors),
 * which is O(V + E) in memory and lets us iterate a node's dependencies in
 * O(out-degree) — ideal for the traversal algorithms in ./analyzers.
 */
export class DependencyGraph {
  readonly nodes: string[];
  private readonly out = new Map<string, Set<string>>();
  private readonly inn = new Map<string, Set<string>>();

  constructor(nodes: string[], edges: Pick<Edge, "from" | "to">[]) {
    this.nodes = [...nodes].sort();
    for (const n of this.nodes) {
      this.out.set(n, new Set());
      this.inn.set(n, new Set());
    }
    for (const { from, to } of edges) {
      if (!this.out.has(from) || !this.out.has(to)) continue;
      this.out.get(from)!.add(to);
      this.inn.get(to)!.add(from);
    }
  }

  /** Files that `node` imports, sorted for deterministic traversal. */
  successors(node: string): string[] {
    return [...(this.out.get(node) ?? [])].sort();
  }

  /** Files that import `node`. */
  predecessors(node: string): string[] {
    return [...(this.inn.get(node) ?? [])].sort();
  }

  hasEdge(from: string, to: string): boolean {
    return this.out.get(from)?.has(to) ?? false;
  }

  /** Efferent coupling: number of distinct files this node imports. */
  fanOut(node: string): number {
    return this.out.get(node)?.size ?? 0;
  }

  /** Afferent coupling: number of distinct files importing this node. */
  fanIn(node: string): number {
    return this.inn.get(node)?.size ?? 0;
  }

  get edgeCount(): number {
    let total = 0;
    for (const set of this.out.values()) total += set.size;
    return total;
  }
}

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { analyze, VERSION } from "./analyze.js";
import { loadConfig } from "./config.js";
import type { ArchGuardConfig, Grade } from "./types.js";

/** One analysed commit. */
export interface HistoryPoint {
  sha: string;
  shortSha: string;
  date: string; // ISO 8601 author date
  author: string;
  message: string;
  /** False when the analysed folder didn't exist yet (or had no source files) at this commit. */
  analyzed: boolean;
  files: number;
  edges: number;
  health: number;
  grade: Grade;
  driftPoints: number;
  cycles: number;
  filesInCycles: number;
  layerViolations: number;
  godFiles: number;
  orphanFiles: number;
  unresolved: number;
}

export interface Regression {
  from: string; // short sha before
  to: string; // short sha after
  message: string; // message of the commit that caused the drop
  delta: number; // health change (negative = worse)
}

export interface History {
  meta: {
    tool: "archguard";
    kind: "history";
    version: string;
    repo: string;
    subpath: string;
    generatedAt: string;
    durationMs: number;
    configSource: string;
    strategy: "latest" | "spread";
  };
  points: HistoryPoint[]; // oldest first
  trend: {
    firstHealth: number | null;
    lastHealth: number | null;
    delta: number | null;
    /** The biggest single-commit drops in health, worst first. */
    regressions: Regression[];
    /** The biggest single-commit improvements, best first. */
    improvements: Regression[];
  };
}

export interface HistoryOptions {
  /** How many commits to analyse (default 30). */
  commits?: number;
  /** "latest" = the N most recent commits; "spread" = N commits evenly spaced across all history. */
  strategy?: "latest" | "spread";
  /** Branch, tag or commit to walk back from (default HEAD). */
  ref?: string;
  configPath?: string;
  config?: ArchGuardConfig;
  onProgress?: (done: number, total: number, sha: string) => void;
}

const git = (cwd: string, args: string[]) =>
  execFileSync("git", args, { cwd, encoding: "utf8", maxBuffer: 256 * 1024 * 1024, stdio: ["ignore", "pipe", "pipe"] });

/**
 * Phase 4 — architecture drift over time.
 *
 * For each selected commit we export that commit's files into a temporary folder
 * with `git archive` (read-only: the user's working tree, index and branches are
 * never touched), run the normal analysis on it, and record the score.
 *
 * The CURRENT config is used for every commit, so all commits are judged by the
 * same rules and their scores are directly comparable.
 */
export async function analyzeHistory(targetDir: string, options: HistoryOptions = {}): Promise<History> {
  const started = Date.now();
  const target = path.resolve(targetDir);
  const commitsWanted = options.commits ?? 30;
  const strategy = options.strategy ?? "latest";
  const ref = options.ref ?? "HEAD";
  if (!Number.isInteger(commitsWanted) || commitsWanted < 1) throw new Error("commits must be a positive integer");

  let repo: string;
  try {
    repo = git(target, ["rev-parse", "--show-toplevel"]).trim();
  } catch {
    throw new Error(`${target} is not inside a git repository`);
  }
  repo = fs.realpathSync(repo);
  const subpath = toPosix(path.relative(repo, fs.realpathSync(target)));

  const { config, source } = options.config
    ? { config: options.config, source: "inline" }
    : loadConfig(target, options.configPath);

  const commits = selectCommits(listCommits(repo, ref), commitsWanted, strategy);
  if (commits.length === 0) throw new Error(`No commits found for ${ref}`);

  const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "archguard-history-"));
  const points: HistoryPoint[] = [];

  try {
    for (const [i, c] of commits.entries()) {
      options.onProgress?.(i, commits.length, c.shortSha);
      const dir = path.join(tmpRoot, c.shortSha);
      fs.mkdirSync(dir);
      const exported = exportCommit(repo, c.sha, subpath, dir);
      const analysisRoot = path.join(dir, subpath);

      let point: HistoryPoint = { ...c, ...EMPTY_METRICS, analyzed: false };
      if (exported && fs.existsSync(analysisRoot)) {
        const report = await analyze(analysisRoot, { config });
        if (report.summary.files > 0) {
          point = {
            ...c,
            analyzed: true,
            files: report.summary.files,
            edges: report.summary.edges,
            health: report.score.health,
            grade: report.score.grade,
            driftPoints: report.score.driftPoints,
            cycles: report.summary.cycles,
            filesInCycles: report.score.filesInCycles,
            layerViolations: report.score.layerViolations,
            godFiles: report.score.godFiles,
            orphanFiles: report.score.orphanFiles,
            unresolved: report.summary.unresolved,
          };
        }
      }
      points.push(point);
      fs.rmSync(dir, { recursive: true, force: true }); // keep disk use to one commit at a time
    }
    options.onProgress?.(commits.length, commits.length, "");
  } finally {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  }

  return {
    meta: {
      tool: "archguard",
      kind: "history",
      version: VERSION,
      repo,
      subpath: subpath || ".",
      generatedAt: new Date().toISOString(),
      durationMs: Date.now() - started,
      configSource: source,
      strategy,
    },
    points,
    trend: computeTrend(points),
  };
}

const EMPTY_METRICS = {
  files: 0, edges: 0, health: 0, grade: "F" as Grade, driftPoints: 0, cycles: 0,
  filesInCycles: 0, layerViolations: 0, godFiles: 0, orphanFiles: 0, unresolved: 0,
};

type CommitInfo = Pick<HistoryPoint, "sha" | "shortSha" | "date" | "author" | "message">;

/** Commits on the first-parent chain (the "main line"), oldest first. */
function listCommits(repo: string, ref: string): CommitInfo[] {
  const SEP = "\x1f";
  const out = git(repo, ["log", "--first-parent", `--format=%H${SEP}%h${SEP}%aI${SEP}%an${SEP}%s`, ref]);
  return out
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [sha, shortSha, date, author, message] = line.split(SEP);
      return { sha, shortSha, date, author, message };
    })
    .reverse();
}

/** Pick which commits to analyse. Always includes the newest commit. */
export function selectCommits<T>(all: T[], n: number, strategy: "latest" | "spread"): T[] {
  if (all.length <= n) return all;
  if (strategy === "latest") return all.slice(-n);
  if (n === 1) return [all[all.length - 1]];
  // Evenly spaced indices from the first to the last commit, inclusive.
  const picked = new Set<number>();
  for (let k = 0; k < n; k++) picked.add(Math.round((k * (all.length - 1)) / (n - 1)));
  return [...picked].sort((a, b) => a - b).map((i) => all[i]);
}

/**
 * Writes the files of `subpath` at commit `sha` into `dest` (read-only for the repo).
 * Returns false if the path didn't exist at that commit. Also used by the GitHub
 * Action to materialise the PR's base commit next to the checked-out head.
 */
export function exportCommit(repo: string, sha: string, subpath: string, dest: string): boolean {
  const tarFile = `${dest}.tar`;
  try {
    const pathArgs = subpath ? ["--", subpath] : [];
    execFileSync("git", ["archive", "--format=tar", "-o", tarFile, sha, ...pathArgs], { cwd: repo, stdio: "pipe" });
  } catch {
    return false; // e.g. the folder didn't exist yet at this commit
  }
  try {
    execFileSync("tar", ["-xf", tarFile, "-C", dest], { stdio: "pipe" });
    return true;
  } finally {
    fs.rmSync(tarFile, { force: true });
  }
}

export function computeTrend(points: HistoryPoint[]): History["trend"] {
  const analysed = points.filter((p) => p.analyzed);
  const steps: Regression[] = [];
  for (let i = 1; i < analysed.length; i++) {
    const delta = analysed[i].health - analysed[i - 1].health;
    if (delta !== 0) {
      steps.push({ from: analysed[i - 1].shortSha, to: analysed[i].shortSha, message: analysed[i].message, delta });
    }
  }
  const first = analysed[0]?.health ?? null;
  const last = analysed[analysed.length - 1]?.health ?? null;
  return {
    firstHealth: first,
    lastHealth: last,
    delta: first !== null && last !== null ? last - first : null,
    regressions: steps.filter((s) => s.delta < 0).sort((a, b) => a.delta - b.delta).slice(0, 5),
    improvements: steps.filter((s) => s.delta > 0).sort((a, b) => b.delta - a.delta).slice(0, 5),
  };
}

function toPosix(p: string): string {
  return p.split(path.sep).join("/");
}

